def small():
    return nn.Sequential(nn.Linear(10, 16), nn.ReLU(), nn.Linear(16, 3))


def wide():
    return nn.Sequential(nn.Linear(10, 64), nn.ReLU(), nn.Linear(64, 3))

BUILDERS = {"small": small, "wide": wide}


def build(name):
    return BUILDERS[name]()

def predict(checkpoint, features):
    student = build("small")
    student.load_state_dict(torch.load(checkpoint, map_location="cpu", weights_only=True))
    student.eval()
    return student(features).argmax(dim=-1)
